package bo.soboce.comedor;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import org.json.*;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class MobileControlTest {
 PeerDatabaseTest fixture;PeerEngine engine;MobileControl api;PeerConfig config;
 @Before public void setup()throws Exception{fixture=new PeerDatabaseTest();fixture.setup();fixture.context.deleteDatabase("ios-control-test.db");config=fixture.sharedConfig(0,"c".repeat(64));engine=new PeerEngine(fixture.context,config,"ios-control-test.db");api=new MobileControl(engine);fixture.elect(new PeerEngine[]{engine},0,1);}
 @After public void cleanup(){if(engine!=null){engine.close();engine.db.close();}fixture.context.deleteDatabase("ios-control-test.db");fixture.cleanup();}
 JSONObject envelope(JSONObject request)throws Exception{String payload=request.toString(),nonce=PeerConfig.random();long now=System.currentTimeMillis();return new JSONObject().put("time",now).put("nonce",nonce).put("payload",payload).put("signature",config.mac("control-request|"+now+"|"+nonce+"|"+payload));}
 JSONObject call(JSONObject request)throws Exception{JSONObject sent=envelope(request),reply=api.handle(sent);assertEquals(config.mac("control-reply|"+sent.getString("nonce")+"|"+reply.getString("payload")),reply.getString("signature"));JSONObject body=new JSONObject(reply.getString("payload"));assertEquals(1,body.getInt("controlProtocol"));return body;}
 JSONObject scan(String meal)throws Exception{return new JSONObject().put("action","scan").put("request",fixture.sharedRequest(0,meal)).put("operator",config.operator(-1)).put("epoch",1);}
 @Test public void authenticatesAndRejectsTamperingAndReplay()throws Exception{JSONObject request=envelope(new JSONObject().put("action","bootstrap"));JSONObject reply=api.handle(request);assertEquals(config.cluster,new JSONObject(reply.getString("payload")).getString("cluster"));try{api.handle(request);fail("Replay accepted");}catch(IllegalArgumentException expected){}JSONObject changed=envelope(new JSONObject().put("action","bootstrap")).put("payload","{\"action\":\"sync\"}");try{api.handle(changed);fail("Tampering accepted");}catch(IllegalArgumentException expected){}assertEquals(0,engine.offline.records().size());}
 @Test public void scansOnceAndRecoversSameReceiptWithoutAnotherGrant()throws Exception{JSONObject request=scan("almuerzo"),first=call(request);assertEquals("accepted",first.getString("status"));assertFalse(first.getString("receipt").isEmpty());JSONObject again=call(new JSONObject().put("action","recover").put("request",request.getJSONObject("request")));assertEquals("recovered",again.getString("status"));assertEquals(first.getString("receipt"),again.getString("receipt"));assertEquals("duplicate",call(scan("dieta")).getString("status"));assertEquals(1,engine.offline.records().size());}
 @Test public void unknownRecoveryNeverCreatesAMeal()throws Exception{JSONObject response=call(new JSONObject().put("action","recover").put("request",fixture.sharedRequest(0,"almuerzo")));assertFalse(response.getBoolean("ok"));assertFalse(response.getBoolean("definitive"));assertEquals(0,engine.offline.records().size());}
 @Test public void oldEpochRejectsBeforeWritingAndFollowerDoesNotGrant()throws Exception{JSONObject r=call(scan("almuerzo").put("epoch",2));assertFalse(r.getBoolean("ok"));assertTrue(r.getBoolean("definitive"));long now=android.os.SystemClock.elapsedRealtime();engine.shared.lease.update(new JSONObject().put("owner","d".repeat(64)).put("boot",PeerConfig.random()).put("epoch",2).put("remaining",30000),now,now);assertFalse(call(scan("almuerzo")).getBoolean("ok"));}
 @Test public void paginatesRosterWithoutLeakingTunnelOrNetworkSecrets()throws Exception{JSONObject boot=call(new JSONObject().put("action","bootstrap"));assertFalse(boot.has("tunnel"));assertFalse(boot.has("networkKey"));assertEquals(4,boot.getJSONArray("legacyOperators").length());for(int i=0;i<205;i++){JSONObject p=new JSONObject(config.seed.getJSONArray("people").getJSONObject(0).toString()).put("id",String.format("CUSTOM-%04d",i));engine.db.save("people",p.getString("id"),p);}JSONObject page=call(new JSONObject().put("action","page").put("kind","people").put("after",""));assertEquals(200,page.getJSONArray("items").length());assertTrue(page.getBoolean("more"));JSONObject next=call(new JSONObject().put("action","page").put("kind","people").put("after",page.getString("after")));assertEquals(6,next.getJSONArray("items").length());assertFalse(next.getBoolean("more"));}
 @Test public void invalidReceiptRollsBackWorkerEnrollmentInSameBatch()throws Exception{String qr=new RosterLedger(engine.db,config).add(fixture.enrollmentRequest("0012345","Prueba"),System.currentTimeMillis()).getString("qr");engine.db.getWritableDatabase().execSQL("DELETE FROM people WHERE id='CI-0012345'");engine.db.getWritableDatabase().execSQL("DELETE FROM roster_events");JSONObject broken=new JSONObject().put("body","{}").put("signature","0".repeat(64));JSONObject r=call(new JSONObject().put("action","sync").put("roster",new JSONArray().put(qr)).put("events",new JSONArray().put(broken.toString())));assertFalse(r.getBoolean("ok"));assertNull(engine.db.get("people","CI-0012345"));}
 @Test public void disallowsBillingActionsAndRequiresIdentityConfirmationForBinding()throws Exception{assertFalse(call(new JSONObject().put("action","setPrice")).getBoolean("ok"));JSONObject r=call(new JSONObject().put("action","walletBind").put("personId","SAP-12345").put("identityChecked",false));assertFalse(r.getBoolean("ok"));assertTrue(r.getBoolean("definitive"));}
}
